use crate::position::AccountBalance;

pub fn to_json(balances: &[AccountBalance]) -> serde_json::Value {
    serde_json::Value::Array(
        balances
            .iter()
            .map(|b| {
                serde_json::json!({
                    "account": b.account,
                    "asOf": b.as_of,
                    // SIGNED, and labelled as such — a reader that took this for a printed figure
                    // would negate every card balance back to wrong.
                    "signedMinor": b.balance.minor,
                    "currency": b.balance.currency.as_str(),
                })
            })
            .collect(),
    )
}
